    "每三個月決策一次。": "Entscheidet einmal alle drei Monate.",
    "每場災難的嚴重度、直接死亡、之後每年多造成的死亡、升溫與收成變化": "Schwere jeder Katastrophe, direkte Todesfälle, zusätzliche Todesfälle in den Folgejahren, Änderungen bei Erwärmung und Ernte",
    "每年一月依世界當時的狀態算出各種風險的機率，再用這個世界的種子亂數判定。": "Jeden Januar wird die Wahrscheinlichkeit jedes Risikos aus dem damaligen Weltzustand berechnet und dann mit den Zufallszahlen aus dem Seed dieser Welt entschieden.",
