    "：AI 能力（人工智慧、通用 AI、超級智慧）和安全程度（AI 安全研究、可解釋 AI、事故後的教訓）差距越大越危險。": ": Je größer die Lücke zwischen KI-Fähigkeit (KI, allgemeine KI, Superintelligenz) und Sicherheit (KI-Sicherheitsforschung, erklärbare KI, Lehren aus Unfällen), desto gefährlicher.",
    "：同時普及核能與火箭的國家是擁核國。": ": Länder, in denen Kernkraft und Raketen beide verbreitet sind, gelten als Atommächte.",
    "：地球人口跌到高峰的 {0}% 以下就是文明崩潰，結局名稱取最近 40 年造成死亡最多的原因；超級智慧失控直接結束。": ": Fällt die Erdbevölkerung unter {0} % ihres Höchststands, bricht die Zivilisation zusammen, und das Ende wird nach der häufigsten Todesursache der letzten 40 Jahre benannt; eine außer Kontrolle geratene Superintelligenz beendet alles sofort.",
    "：基因工程與合成生物學越普及、醫療越差、世界在打仗時，機率越高。": ": Je verbreiteter Gentechnik und synthetische Biologie, je schlechter das Gesundheitswesen und je mehr Krieg in der Welt, desto höher die Wahrscheinlichkeit.",
    "：完成「火星殖民」後建立殖民地，人口成長受容量限制；達到 100 萬人可以自給自足，地球毀滅時人類仍能延續。": ": Nach der „Marskolonisierung“ wird eine Kolonie gegründet; ihr Wachstum ist durch die Kapazität begrenzt; ab 1 Million Menschen ist sie selbstversorgend, und die Menschheit überlebt selbst die Zerstörung der Erde.",
    "：暖化＝起點暖化＋累積化石燃料使用量 × 係數。": ": Erwärmung = Anfangserwärmung + kumulierter Verbrauch fossiler Brennstoffe × Koeffizient.",
    "：每年很小的自然機率；行星防禦普及後可以偏轉。": ": eine sehr kleine natürliche Wahrscheinlichkeit pro Jahr; ist planetare Verteidigung verbreitet, können Asteroiden abgelenkt werden.",
